css:
@page { size: letter; margin: 0.45in 0.55in; } body { font: 12.5px Georgia, 'Times New Roman', serif; color: #1d1d1b; margin: 0; }
.hd { display: flex; justify-content: space-between; border-bottom: 2px solid #1d1d1b; padding-bottom: 4px; margin-bottom: 6px; } .hd b { font-size: 17px; } .hd { gap: 14px; } .hd > .nm { white-space: nowrap; flex-shrink: 0; }
.nm { font: 12px system-ui, sans-serif; } .sec { font: 700 14px system-ui, sans-serif; margin: 12px 0 4px; padding: 3px 8px; background: #eef2f7; border-left: 4px solid #1f5fa8; break-after: avoid; }
p { margin: 4px 0; line-height: 1.35; } .note { margin: 7px 0; line-height: 2.1; } .icans { font-size: 12px; margin: 2px 0 4px; } .icans li { margin: 0; }
table { border-collapse: collapse; width: 100%; margin: 4px 0; break-inside: avoid; } th, td { border: 1px solid #777; padding: 2px 6px; text-align: left; font-size: 12px; } th { background: #f3f3ee; font: 600 12px system-ui, sans-serif; }
.line { border-bottom: 1px solid #999; height: 24px; } .box { border: 1px dashed #aaa; border-radius: 6px; margin: 4px 0; }
.prob { break-inside: avoid; margin: 6px 0; padding-top: 4px; border-top: 1px solid #ddd; } .prob .lab { font: 700 12px system-ui, sans-serif; margin-bottom: 2px; }
.prob img { display: block; } .fig { margin: 2px 0 0 18px; } .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 18px; }
.ticket { height: 4.85in; box-sizing: border-box; padding: 4px 2px; overflow: hidden; } .cut { border-top: 2px dashed #888; margin: 4px 0; position: relative; } .cut span { position: absolute; left: 50%; top: -9px; background: #fff; padding: 0 6px; font: 11px system-ui; color: #666; }
.cards { display: grid; grid-template-columns: 1fr 1fr; gap: 0; } .card { border: 1px dashed #888; height: 2.2in; display: flex; align-items: center; justify-content: center; }
.strip { height: 1.1cm; border: 1px solid #333; background: #f4e3a1; display: flex; align-items: center; padding-left: 6px; font: 12px system-ui; margin: 3px 0; box-sizing: border-box; }
.tree { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; text-align: center; margin: 6px 0; } .tree div { border: 1.5px solid #333; height: 30px; border-radius: 6px; }
.pb { break-after: page; }
.vocab { border: 1.5px solid #1f5fa8; border-radius: 6px; padding: 3px 10px 4px; margin: 4px 0 6px; font-size: 12px; break-inside: avoid; } .vocab .vt { font: 700 12px system-ui, sans-serif; color: #1f5fa8; } .vocab .vt span { font-weight: 400; color: #555; }
.vocab div.v { line-height: 1.95; } .vocab img.vm { vertical-align: middle; display: inline; } .vocab .bl { display: inline-block; border-bottom: 1px solid #333; height: 1em; vertical-align: -2px; }
